const item = $input.first();
const payload = item.json.payload || item.json.body?.payload || {};
const media = payload.media || {};
const base64 = String(media.base64 || '').replace(/^data:[^;]+;base64,/, '');
const mimetype = media.mimetype || 'image/jpeg';
if (!base64) {
  throw new Error('Image Evolution sans base64. Activez webhook.base64 sur l instance Evolution.');
}
return [{
  json: item.json,
  binary: {
    data: {
      data: base64,
      mimeType: mimetype,
      fileName: 'whatsapp-image.' + (mimetype.includes('png') ? 'png' : 'jpg'),
      fileExtension: mimetype.includes('png') ? 'png' : 'jpg',
    },
  },
}];

const item = $input.first();
const payload = item.json.payload || item.json.body?.payload || {};
const media = payload.media || {};
const base64 = String(media.base64 || '').replace(/^data:[^;]+;base64,/, '');
const mimetype = media.mimetype || 'audio/ogg';
const extension = mimetype.includes('mpeg') || mimetype.includes('mp3') ? 'mp3'
  : mimetype.includes('wav') ? 'wav'
  : mimetype.includes('webm') ? 'webm'
  : mimetype.includes('m4a') || mimetype.includes('mp4') ? 'm4a'
  : 'ogg';
if (!base64) {
  throw new Error('Audio Evolution sans base64. Activez webhook.base64 sur l instance Evolution.');
}
return [{
  json: item.json,
  binary: {
    data: {
      data: base64,
      mimeType: mimetype,
      fileName: 'whatsapp-audio.' + extension,
      fileExtension: extension,
    },
  },
}];

const items = $input.all();

// 1. Fusionner les textes
const contenus = items
  .map(i => i.json.contenu)
  .filter(Boolean);

let messageFusionne = contenus.join(' [SUITE] ');

// 2. RÃ©cupÃ©rer les IDs pour la mise Ã  jour
const idsToUpdate = items.map(i => i.json.id);

// 3. Infos client
const client = items[0].json.client;
// Extract phone: "Name : 225... @c.us" -> "225..."
const phone = client.split(' : ').pop().replace('@c.us', '').replace('@s.whatsapp.net', '');

return [
  {
    json: {
      message: messageFusionne,
      client: client,
      phone: phone,
      batchIds: idsToUpdate
    }
  }
];

const message = $json.message || '';
const match = message.match(/Ref Commande:\s*([A-F0-9]+)/i);
return {
  ref: match ? match[1] : null,
  phone: $json.phone
};

const input = $input.first().json;
const body = input.body || input;
const query = input.query || {};
const data = body.data || body.message || {};
const key = data.key || {};
const event = body.event || '';

if (event && !['MESSAGES_UPSERT', 'messages.upsert'].includes(event)) {
  return [];
}

const msg = data.message || data;
const instanceName = body.instance || body.instanceName || query.seller || 'unknown';
const remoteJid = key.remoteJid || data.remoteJid || data.chatId || body.remoteJid || body.chatId || '';
const messageId = key.id || data.id || body.id || String(Date.now());
const pushName = data.pushName || body.pushName || 'Client';
const isFromMe = Boolean(key.fromMe || data.fromMe || body.fromMe);

let text =
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.imageMessage?.caption ||
  msg.videoMessage?.caption ||
  data.messageText ||
  body.text ||
  '';

const mimetype =
  msg.imageMessage?.mimetype ||
  msg.audioMessage?.mimetype ||
  msg.videoMessage?.mimetype ||
  msg.documentMessage?.mimetype ||
  '';

const mediaBase64 =
  msg.base64 ||
  data.base64 ||
  body.base64 ||
  msg.imageMessage?.base64 ||
  msg.audioMessage?.base64 ||
  msg.documentMessage?.base64 ||
  msg.imageMessage?.jpegThumbnail ||
  '';

const isImage = mimetype.includes('image');
const isAudio = mimetype.includes('audio');
const hasMedia = Boolean(mimetype && mediaBase64);

if (!text && isImage && !hasMedia) {
  text = 'Le client a envoye une image, mais le fichier image n est pas disponible. Repondez simplement que la photo est recue et demandez quel modele ou detail il cherche.';
}

if (!text && isAudio && !hasMedia) {
  text = 'Le client a envoye un vocal, mais le fichier audio n est pas disponible. Demandez lui d ecrire sa demande en quelques mots.';
}

if (!text && !hasMedia) {
  return [];
}

const payload = {
  id: messageId,
  from: remoteJid,
  body: text,
  hasMedia,
  media: { mimetype, url: '', caption: text, base64: mediaBase64 },
  _data: { notifyName: pushName },
};
const customerPhone = String(remoteJid || '').replace(/\D/g, '');

return [{
  json: {
    source: 'evolution',
    event,
    instanceName,
    seller: query.seller || instanceName,
    sellerSlug: query.seller || instanceName,
    query,
    isFromMe,
    customerPhone,
    payload,
    body: {
      session: instanceName,
      payload,
      event: body.event,
      instance: instanceName,
      isFromMe,
      customerPhone,
    },
    raw: body,
  }
}];

const seller = $('Identify Seller').first().json;
const nl = String.fromCharCode(10);
const orders = $input.all().map(item => item.json).filter(order => Object.keys(order).length > 0);
const products = $('Get Products').all().map(item => item.json).map(product => ({
  id: product.id,
  name: product.name,
  price: product.price,
  stock_quantity: product.stock_quantity,
  image_url: product.image_url,
  description: product.description,
  product_variants: product.product_variants || [],
  product_keywords: product.product_keywords || '',
  product_url: 'https://tikchop.app/' + seller.slug + '?product=' + product.id,
}));
const shop = $('Get Shop Info').all().map(item => item.json)[0] || {};
const productsText = products.length
  ? products.filter(product => Number(product.stock_quantity || 0) > 0).slice(0, 3).map((product, index) => {
      const stock = Number(product.stock_quantity || 0);
      const availability = stock > 0 ? 'DISPO (' + stock + ')' : 'INDISPONIBLE';
      const variants = Array.isArray(product.product_variants) && product.product_variants.length ? ' - Variantes: ' + product.product_variants.slice(0, 4).map(v => [v.label || v.size || v.color, v.stock ? ('stock ' + v.stock) : ''].filter(Boolean).join(' ')).join(', ') : '';
      const keywords = product.product_keywords ? ' - Mots cles: ' + product.product_keywords : '';
      return (index + 1) + '. ' + product.name + ' - ' + Number(product.price || 0).toLocaleString('fr-FR') + ' CFA - ' + (product.description || 'Description a confirmer') + variants + keywords;
    }).join(nl)
  : 'Aucun produit publie.';
const ordersText = orders.length
  ? orders.map(order => 'Commande ' + (order.order_ref || order.id) + ' - ' + order.status + ' - ' + Number(order.total_amount || 0).toLocaleString('fr-FR') + ' CFA').join(nl)
  : 'Aucune commande connue pour ce client.';
const shopText = Object.keys(shop).length ? [
  'Boutique: ' + (shop.name || seller.name || ''),
  'Livraison: ' + (shop.delivery_payment_timing || 'non renseignee'),
  'Frais: ' + Number(shop.fixed_delivery_fee || 0).toLocaleString('fr-FR') + ' CFA',
  shop.bot_tone ? 'Ton boutique: ' + shop.bot_tone : '',
  shop.bot_greeting ? 'Accueil boutique: ' + shop.bot_greeting : '',
  shop.bot_payment_preferences ? 'Paiements preferes: ' + shop.bot_payment_preferences : '',
  shop.bot_delivery_notes ? 'Notes livraison: ' + shop.bot_delivery_notes : '',
  shop.bot_special_rules ? 'Regles boutique: ' + shop.bot_special_rules : '',
].filter(Boolean).join(nl) : 'Infos livraison non renseignees.';

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const message = $('Fusion Pro').first().json.message || '';
const normalizedMessage = normalize(message);
const wantsCatalog = /\b(stock|catalogue|article|articles|produit|produits|disponible|disponibles|photo|photos|image|images|prix|combien|cout|coute|modeles|modele|voir|montre|envoie|envoyer|envoi)\b/i.test(normalizedMessage);
const orderIntent = /\b(je prends|je prend|j achete|jachete|acheter|commande|commander|je veux commander|je vais prendre|c est bon pour|interesse|interessee|preneur|garde moi|reserve|reserver|mettre de cote|mets de cote)\b/i.test(normalizedMessage);
const indexMatch = normalizedMessage.match(/(?:numero|article|produit|modele|mod?le|le|la|l)?\s*(\d{1,2})\b/);
const quantityMatch = normalizedMessage.match(/(?:quantite|qte|qty|nombre|prends en|prendre en|x)\s*(\d{1,2})|(?:\b(\d{1,2})\s*(?:pieces?|pcs?|articles?)\b)/);
const quantity = Math.max(1, Math.min(20, Number(quantityMatch?.[1] || quantityMatch?.[2] || 1)));
const stopWords = new Set(['avec','pour','dans','vous','nous','veux','prendre','commande','commander','article','produit','taille','prix','stock','celui','celle','bonjour','salut','bonsoir']);
const messageTokens = new Set(normalizedMessage.split(/\s+/).filter(token => token.length > 2 && !stopWords.has(token)));

const scoredProducts = products.map((product, index) => {
  const productName = normalize(product.name);
  const productExtra = normalize((product.description || '') + ' ' + (product.product_keywords || '') + ' ' + (Array.isArray(product.product_variants) ? product.product_variants.map(v => [v.label, v.size, v.color].filter(Boolean).join(' ')).join(' ') : ''));
  const productTokens = (productName + ' ' + productExtra).split(/\s+/).filter(token => token.length > 2 && !stopWords.has(token));
  let score = 0;
  if (productName && normalizedMessage.includes(productName)) score += 20;
  if (indexMatch && Number(indexMatch[1]) === index + 1) score += 15;
  for (const token of productTokens) {
    if (messageTokens.has(token)) score += 4;
    else if (normalizedMessage.includes(token)) score += 2;
  }
  return { product, index, score };
}).sort((a, b) => b.score - a.score);

const best = scoredProducts[0];
const second = scoredProducts[1];
const matchedProduct = best && best.score > 0 ? best.product : null;
const ready = Boolean(orderIntent && best && best.score > 0 && (!second || best.score >= second.score + 2) && Number(best.product.stock_quantity || 0) >= quantity);
const orderDraft = ready ? {
  ready: true,
  quantity,
  product: best.product,
  total_amount: Number(best.product.price || 0) * quantity,
  customer_phone: $('Fusion Pro').first().json.phone,
} : {
  ready: false,
  intent: orderIntent,
  reason: orderIntent ? 'product_unclear_or_stock_missing' : 'no_order_intent',
};

const paymentIntent = /\b(wave|orange money|orange|om|mtn|moov|mobile money|mobile|payer|paiement|paye|payement|carte|visa|mastercard|lien de paiement|paiement en ligne)\b/i.test(normalizedMessage);
const pendingOrders = orders
  .filter(order => order.status === 'PENDING' && Number(order.total_amount || 0) > 0 && String(order.customer_phone || '') === String($('Fusion Pro').first().json.phone || ''))
  .sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
const paymentDraft = paymentIntent && pendingOrders.length ? {
  ready: true,
  order: pendingOrders[0],
  amount: Number(pendingOrders[0].total_amount || 0) + Number(pendingOrders[0].delivery_fee || 0),
  customer_phone: $('Fusion Pro').first().json.phone,
} : {
  ready: false,
  intent: paymentIntent,
  reason: paymentIntent ? 'no_pending_order' : 'no_payment_intent',
};

const inStockProducts = products.filter(product => Number(product.stock_quantity || 0) > 0);
const followProduct = (best && best.score > 0 && Number(best.product.stock_quantity || 0) > 0) ? best.product : inStockProducts[0];
const followUpDraft = wantsCatalog && !orderIntent && !paymentIntent && followProduct && !pendingOrders.length ? {
  ready: true,
  started_at: new Date().toISOString(),
  seller_id: seller.id,
  seller_name: seller.name,
  customer_phone: $('Fusion Pro').first().json.phone,
  product_name: followProduct.name,
  product_price: Number(followProduct.price || 0),
} : {
  ready: false,
  reason: wantsCatalog ? 'order_or_payment_or_pending_exists' : 'no_catalog_interest',
};

return [{ json: { orders, products, shop, productsText, ordersText, shopText, wantsCatalog, orderIntent, paymentIntent, matchedProduct, orderDraft, paymentDraft, followUpDraft } }];

const items = $input.all();
const first = items.find(item => (item.json.output || '').trim()) || items[0];
if (!first) return [];
const context = $('Prepare AI Context').first().json || {};
let output = String(first.json.output || '').replace('[SEND_BROCHURE]', '').trim();
if (context.wantsCatalog && output && !/Wave|Orange Money|MTN|Moov|mobile money/i.test(output)) {
  output += String.fromCharCode(10) + 'Paiement possible par Wave, Orange Money, MTN/Moov ou carte.';
}
return [{ json: { ...first.json, output } }];

const context = $('Prepare AI Context').first().json;
const rawMessage = String($('Fusion Pro').first().json.message || '');
const message = rawMessage.toLowerCase();
const explicitPhotoRequest = /(photo|photos|image|images|voir|montre|montrer|envoie|envoyer|envoi|montrez)/i.test(message);
if (!explicitPhotoRequest) return [];

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const normalizedMessage = normalize(rawMessage);
const indexMatch = normalizedMessage.match(/(?:numero|article|produit|modele|le|la|l)?\s*(\d{1,2})\b/);
const products = (context.products || []).filter(product => product.image_url && Number(product.stock_quantity || 0) > 0);
let product = null;
let tokenMatchScore = 0;

if (indexMatch) product = products[Number(indexMatch[1]) - 1] || null;
if (!product && context.matchedProduct?.image_url) product = products.find(item => item.id === context.matchedProduct.id) || null;
if (!product) {
  const tokens = new Set(normalizedMessage.split(' ').filter(token => token.length > 2));
  const scored = products
    .map(item => ({
      item,
      score: normalize([item.name, item.description, item.product_keywords, Array.isArray(item.product_variants) ? item.product_variants.map(v => [v.label, v.size, v.color].filter(Boolean).join(' ')).join(' ') : ''].filter(Boolean).join(' ')).split(' ').filter(token => tokens.has(token)).length,
    }))
    .sort((a, b) => b.score - a.score)[0];
  if (scored?.score > 0) {
    product = scored.item;
    tokenMatchScore = scored.score;
  }
}

if (!product) return [];

const nl = String.fromCharCode(10);
const number = String($('Normalize Evolution Payload').first().json.body.payload.from || '').replace(/\D/g, '');
const caption = [
  product.name,
  Number(product.price || 0).toLocaleString('fr-FR') + ' CFA',
  'Disponible. Si ca vous plait, je peux le mettre de cote pour vous.'
].join(nl);

return [{ json: {
  number,
  mediatype: 'image',
  mimetype: 'image/jpeg',
  media: product.image_url,
  fileName: (product.name || 'produit').replace(/[^a-z0-9_-]+/gi, '-').toLowerCase() + '.jpg',
  caption,
  matchedBy: indexMatch ? 'index' : context.matchedProduct?.id === product.id ? 'product' : 'tokens',
  tokenMatchScore,
} }];

const orderRaw = $('Check Follow-up Orders').all().map(item => item.json);
const orders = orderRaw.flatMap(item => Array.isArray(item) ? item : [item]).filter(item => item && item.id);
if (orders.length) return [];
const followRaw = $input.all().map(item => item.json);
const recentFollowups = followRaw.flatMap(item => Array.isArray(item) ? item : [item]).filter(item => item && (item.id || item.created_at));
if (recentFollowups.length) return [];
const draft = $('Prepare AI Context').first().json.followUpDraft || {};
if (!draft.ready) return [];
const hour = new Date().getHours();
const salutation = hour >= 18 ? 'Bonsoir' : 'Bonjour';
const price = Number(draft.product_price || 0).toLocaleString('fr-FR') + ' CFA';
const text = [
  salutation + ", c'est " + (draft.seller_name || 'la boutique') + '.',
  draft.product_name + ' est toujours dispo a ' + price + '.',
  'Je peux vous le reserver si vous confirmez.'
].join(String.fromCharCode(10));
return [{ json: { number: draft.customer_phone, text } }];

const raw = $input.all().map(item => item.json);
const records = raw.flatMap(item => Array.isArray(item) ? item : [item]).filter(item => item && item.paused_until);
if (records.length) return [];
return [{ json: $('Normalize Evolution Payload').first().json }];
